"""Read the oracle of each test generated by pankti-generate: the return value observed in production.

pankti-generate writes one of these assertions at the end of each test:
    Assert.assertEquals(<literal>, receivingObject.m(...));                     primitive, null
    Assert.assertEquals(expectedObject, receivingObject.m(...));                object deserialised from
    Assert.assertTrue(Arrays.equals(expectedObject, receivingObject.m(...)));   returnedObjectStr (XStream XML)
observed_values() returns, for every test, the observed value in a form that can be compared with the default
values of Descartes' extreme mutators (see mutant_killed()).
"""
import re
import xml.etree.ElementTree as ET
from pathlib import Path

TEST = re.compile(r"    @Test\n    public void (test\w+)\(\) throws Exception \{\n(.*?)\n    \}\n", re.S)
ASSERT = re.compile(r"Assert\.(?:assertEquals\((.+?), receivingObject\.\w+\(|assertTrue\(Arrays\.equals\(expectedObject, )")
EXPECTED_TYPE = re.compile(r"\n\s+([\w.$\[\]]+) expectedObject = deserializeObject")
JAVA_STRING = re.compile(r'"((?:[^"\\]|\\.)*)"')
NUMBER_TAGS = {"int", "long", "short", "byte", "float", "double"}


def java_unescape(s):
    return re.sub(r'\\(u[0-9a-fA-F]{4}|.)', lambda m: chr(int(m.group(1)[1:], 16)) if m.group(1)[0] == "u"
                  else {"n": "\n", "t": "\t", "r": "\r", "b": "\b", "f": "\f"}.get(m.group(1), m.group(1)), s)


def xml_value(xml):
    """Observed value from the XStream XML of a returned object."""
    root = ET.fromstring(xml)
    tag = root.tag
    if tag == "null":
        return ("null", None)
    if tag == "string":
        return ("str", root.text or "")
    if tag == "boolean":
        return ("bool", root.text == "true")
    if tag in NUMBER_TAGS:
        return ("num", float(root.text))
    if tag == "char":
        return ("char", root.text or "")
    if tag.endswith("-array"):
        return ("array", len(list(root)))
    if len(root) == 0 and (root.text or "").strip() and not root.attrib:
        return ("enum", root.text.strip())  # an enum constant: element with text only
    return ("object", tag)


def literal_value(text):
    text = text.strip()
    if text == "null":
        return ("null", None)
    if text in ("true", "false"):
        return ("bool", text == "true")
    m = re.fullmatch(r"\(\w+\)\s*(-?[\d.]+)|(-?[\d.]+(?:[eE]-?\d+)?)[fFdDlL]?", text)
    if m:
        return ("num", float(m.group(1) or m.group(2)))
    if text.startswith('"'):
        return ("str", java_unescape(text[1:-1]))
    if text.startswith("'"):
        return ("char", java_unescape(text[1:-1]))
    raise ValueError(f"unknown literal {text!r}")


def test_value(body):
    """(kind, value) observed by one test, from its body."""
    m = ASSERT.search(body)
    if m is None:
        raise ValueError("no assertion")
    if m.group(1) is not None and m.group(1) != "expectedObject":
        return literal_value(m.group(1))
    if "returnedObjectStr =" not in body:
        # large values are read from a resource file (fileReturned): a non-null object or a non-empty array
        declared = EXPECTED_TYPE.search(body).group(1)
        return ("array", None) if declared.endswith("[]") else ("object", declared)
    start = body.index("returnedObjectStr =")
    xml = "".join(java_unescape(s) for s in JAVA_STRING.findall(body[start:body.index(";", start)]))
    return xml_value(xml)


def observed_values(root):
    """{(test class without the "PanktiGen..." suffix stripped, test name): (kind, value, declared type)}.

    Test classes split by split_test_classes.py (suffix PartN) are reported under the original class name."""
    values = {}
    for java in sorted(Path(root).rglob("Test*PanktiGen*.java")):
        text = java.read_text(encoding="utf-8", errors="replace")
        package = re.search(r"^package ([\w.]+);", text, re.M).group(1)
        cls = package + "." + re.sub(r"Part\d+$", "", java.stem)
        for name, body in TEST.findall(text):
            t = EXPECTED_TYPE.search(body)
            values[(cls, name)] = test_value(body) + ((t.group(1) if t else ""),)
    return values


# Default value returned by each Descartes mutator (configuration of the authors' reports, 21 operators).
MUTANTS = {
    "null": ("null", None), "empty": ("array", 0), "true": ("bool", True), "false": ("bool", False),
    "0": ("num", 0.0), "1": ("num", 1.0), "(short)0": ("num", 0.0), "(short)1": ("num", 1.0),
    "(byte)0": ("num", 0.0), "(byte)1": ("num", 1.0), "0L": ("num", 0.0), "1L": ("num", 1.0),
    "0.0": ("num", 0.0), "1.0": ("num", 1.0), "0.0f": ("num", 0.0), "1.0f": ("num", 1.0),
    "'\\40'": ("char", " "), "'A'": ("char", "A"), '""': ("str", ""), '"A"': ("str", "A"),
}


def mutant_killed(observed, mutator):
    """Does a passing test that observed this value fail when the method returns the mutator's default value?

    The test compares with equals() (Arrays.equals for arrays): it fails when the two values differ. An object
    that is not a string, number, boolean, char or array can only be equal to the null mutant if it is null."""
    kind, value = observed[0], observed[1]
    mkind, mvalue = MUTANTS[mutator]
    if kind in ("object", "enum") or (kind == "array" and value is None):
        return True  # non-null object or enum constant, or non-empty array read from a file, vs a default value
    return (kind, value) != (mkind, mvalue)
